def rects(g,minh=2):
    H,W=len(g),len(g[0]); out=[]
    for i in range(H):
        j=0
        while j<W:
            col=g[i][j]; s=j
            while j+1<W and g[i][j+1]==col: j+=1
            w=j-s+1
            k=i
